using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.InteropServices;using System.Windows.Forms;
namespace HexMapEditor.Tests
{
 internal static class Patch081Tests
 {
  const BindingFlags P=BindingFlags.Instance|BindingFlags.NonPublic;
  static object Get(object o,string n){return o.GetType().GetField(n,P).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,P).SetValue(o,v);}
  static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(P).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}
  static void Check(bool b,string m){if(!b)throw new Exception(m);}
  static MapData Data(){return MainWindow.CreateProjectData(15,10,"PointyTop","Próba 0.8.1",PresetCatalog.Default());}
  static void Key(object o,Keys key){Call(o,"ProcessCmdKey",Message.Create(((Control)o).Handle,0x100,IntPtr.Zero,IntPtr.Zero),key);}
  static void Edit(ScrubNumber n,string text){n.BeginText();((TextBox)Get(n,"input")).Text=text;Key(n,Keys.Enter);}
  static void Fields()
  {
   Check(ScrubNumber.Normalize("3,5",1,-255,255,0)==4&&ScrubNumber.Normalize("-3.5",1,-255,255,0)==-4,"AwayFromZero");
   Check(ScrubNumber.Normalize("-5",10,0,255,0)==0&&ScrubNumber.Normalize("360",10,0,255,0)==255&&ScrubNumber.Normalize("205",10,1,200,0)==200,"Clamp");
   Check(ScrubNumber.Normalize(new string('9',1000),10,0,255,0)==255&&ScrubNumber.Normalize("-"+new string('9',1000),10,0,255,0)==0,"Overflow");
   Check(new[]{"","-","1.","1,","bad","1e2","1a5"}.All(s=>ScrubNumber.Normalize(s,7,0,255,0)==7),"Incomplete/invalid guessed value");
   Check(ScrubNumber.Normalize("1.235",1,0,5,2)==1.24m&&ScrubNumber.Normalize("1,235",1,0,5,2)==1.24m,"Precision");
   using(var t=new NumberTextBox()){t.Text="12";t.SelectAll();Check(!t.Insert("1a5")&&t.Text=="12","Invalid paste changed text");Check(!t.Insert("1,2.3")&&t.Text=="12","Two separators");Check(t.Insert("-3,5")&&t.Text=="-3,5","Valid paste");Check(t.CanUndo,"Paste lost native Undo");t.Undo();Check(t.Text=="12","Native paste Undo");t.SelectAll();var old=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=new CultureInfo("pl-PL");Call(t,"OnKeyDown",new KeyEventArgs(Keys.Decimal));Check(t.Text==",","Numpad decimal");}finally{CultureInfo.CurrentCulture=old;}}
   using(var f=new DarkForm())using(var n=new ScrubNumber{Minimum=0,Maximum=255,Value=125}){f.Controls.Add(n);var label=new Label{Top=60,Text="Neutralne tło"};f.Controls.Add(label);f.Show();n.Finish(true);int ends=0;n.EditFinished+=(s,e)=>ends++;
    n.BeginText();((TextBox)Get(n,"input")).Text="80";Check(n.Value==125,"Applied during typing");var m=Message.Create(label.Handle,0x201,IntPtr.Zero,IntPtr.Zero);Check(!new NumberInputRouter().PreFilterMessage(ref m)&&n.Value==80&&!n.IsEditing&&ends==1,"Neutral click swallowed/not committed");
    n.BeginText();((TextBox)Get(n,"input")).Text="11";Key(n,Keys.Escape);Check(n.Value==80,"Escape");n.BeginScrub(0);n.MoveScrub(80);n.Capture=false;Check(n.Value==80,"Capture cancel");
   }
   using(var w=new MainWindow(Data(),null)){w.Show();Call(w,"CaptureSavedState");long revision=(long)Get(w,"documentRevision");var size=(ScrubNumber)Get(w,"sizePicker");Call(w,"SelectTool",EditorTool.Brush);((ComboBox)Get(w,"shapePicker")).SelectedIndex=(int)BrushShape.Circle;
    Edit(size,"3.5");var undo=(Stack<EditAction>)Get(w,"undo");Check(size.Value==4&&undo.Count==1&&!(bool)Get(w,"dirty")&&(long)Get(w,"documentRevision")==revision,"Tool setting dirtied/revision/step");
    Check((bool)Call(w,"HandleHistoryShortcut",Keys.Control|Keys.Z)&&size.Value==1,"Committed tool keyboard Undo");Check((bool)Call(w,"HandleHistoryShortcut",Keys.Control|Keys.Y)&&size.Value==4,"Committed tool keyboard Redo");
    var map=(MapData)Get(w,"map");var action=new EditAction{BeforeOrientation=map.Orientation,AfterOrientation="FlatTop"};map.Orientation="FlatTop";Call(w,"PushAction",action);Call(w,"MarkDirty");Edit(size,"5");Check(undo.Count==3&&(bool)Get(w,"dirty"),"Order/dirty erased");
    Call(w,"TryHistory",new object[]{false,null});Check(size.Value==4&&(bool)Get(w,"dirty"),"Tool undo dirty");Call(w,"TryHistory",new object[]{false,null});Check(((MapData)Get(w,"map")).Orientation=="PointyTop","Document order");Call(w,"TryHistory",new object[]{false,null});Check(size.Value==1,"First tool undo");Call(w,"TryHistory",new object[]{true,null});Check(size.Value==4,"Tool redo");int count=undo.Count;size.BeginScrub(0);size.MoveScrub(16);size.Finish(true);Check(undo.Count==count&&size.Value==4,"Cancelled tool history");
   }
   using(var d=new EditorColorDialog(Color.FromArgb(125,70,20))){d.Show();d.FinishTextEdit();var rgb=(ScrubNumber[])Get(d,"rgb");Edit(rgb[0],"80");Check(d.SelectedColor.R==80,"RGB commit");Key(d,Keys.Control|Keys.Z);Check(d.SelectedColor.R==125,"Whole dialog Undo");Key(d,Keys.Control|Keys.Y);Check(d.SelectedColor.R==80,"Whole dialog Redo");
    var hex=(TextBox)Get(d,"hex");hex.Text="#123456";d.FinishTextEdit();Key(d,Keys.Control|Keys.Z);Check(d.SelectedColor.R==80,"HEX transaction");Edit(rgb[1],"99");Check(!d.MoveColorHistory(true),"Redo branch");
    var surface=(Control)Get(d,"saturation");var h=(ColorDraftHistory)Get(d,"history");int count=h.Count;Call(surface,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,20,20,0));Call(surface,"OnMouseMove",new MouseEventArgs(MouseButtons.Left,0,130,80,0));Call(surface,"OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,130,80,0));Check(h.Count==count+1,"HSV gesture entries");d.DialogResult=DialogResult.Cancel;}
   using(var d=new EditorColorDialog(Color.Red)){Check(((ColorDraftHistory)Get(d,"history")).Count==0,"New dialog history retained");}
   using(var d=new PaintPickerDialog(Color.FromArgb(125,70,20),null,true)){d.Show();var child=(EditorColorDialog)Get(d,"color");child.FinishTextEdit();Edit(((ScrubNumber[])Get(child,"rgb"))[0],"80");Key(d,Keys.Control|Keys.Z);Check(child.SelectedColor.R==125,"Embedded color undo");Key(d,Keys.Control|Keys.Y);Check(child.SelectedColor.R==80,"Embedded redo");}
   Console.WriteLine("fields PASS: lexical/Decimal/normalization, neutral-click commit, cancel, session tool chronological Undo without dirty/revision, RGB/HEX/HSV local session and embedded picker");
  }
  static void Stamp()
  {
   var map=Data();foreach(string orientation in new[]{"PointyTop","FlatTop"}){map.Orientation=orientation;foreach(var center in new[]{new Point(-1,4),new Point(-1,-1)})foreach(bool filled in new[]{false,true})foreach(var shape in new[]{BrushShape.Circle,BrushShape.Rectangle,BrushShape.Hexagon}){var targets=BrushGeometry.Stamp(map,center,shape,5,5,filled);Check(targets.Count>0&&targets.All(i=>i>=0&&i<map.Cells.Count)&&targets.Distinct().Count()==targets.Count,"Outside stamp clip");Check(ObjectGeometry.Nearest(map,BrushGeometry.Center(map,center.X,center.Y))==center,"Unbounded center");}}
   using(var w=new MainWindow(Data(),null)){w.Show();Set(w,"scale",1f);Set(w,"pan",new PointF(180,180));Set(w,"brushSize",5);Set(w,"brushHeight",5);Set(w,"brushShape",BrushShape.Circle);Set(w,"brushFilled",true);var canvas=(Control)Get(w,"canvas");map=(MapData)Get(w,"map");var world=BrushGeometry.Center(map,-1,3);var p=new Point((int)world.X+180,(int)world.Y+180);var targets=(List<int>)Call(w,"StampAt",p);Check(targets.Count>0,"Fixture outside viewport");
    foreach(var tool in new[]{EditorTool.FogBrush,EditorTool.DarkBrush}){Call(w,"SelectTool",tool);Call(w,"CanvasMouseDown",canvas,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Call(w,"CanvasMouseUp",canvas,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Check(map.Cells.Select((c,i)=>new{c,i}).Where(x=>tool==EditorTool.FogBrush?x.c.Fog:x.c.Darkness).Select(x=>x.i).OrderBy(i=>i).SequenceEqual(targets.OrderBy(i=>i)),"Outside mask actual != preview");Call(w,"TryHistory",new object[]{false,null});Check(map.Cells.All(c=>tool==EditorTool.FogBrush?!c.Fog:!c.Darkness),"Undo outside mask");}
    Call(w,"SelectTool",EditorTool.Brush);Call(w,"CanvasMouseDown",canvas,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Call(w,"CanvasMouseUp",canvas,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Check(targets.All(i=>map.Cells[i].Terrain==map.Presets[0].Terrains[2].Name),"Outside terrain");Call(w,"TryHistory",new object[]{false,null});
    IconAsset asset;using(var bitmap=new Bitmap(8,8))asset=IconAssets.FromBitmap(bitmap,"Próba");var entry=new LibraryIcon{Name="Próba",Asset=asset};((List<LibraryIcon>)Get(w,"libraryIcons")).Add(entry);Call(w,"SelectTool",EditorTool.DarkBucket);Call(w,"SelectIcon",entry.Id);Check((EditorTool)Get(w,"currentTool")==EditorTool.Brush,"Icon from visibility bucket");Call(w,"CanvasMouseDown",canvas,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Call(w,"CanvasMouseUp",canvas,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Check(map.Cells.Select((c,i)=>new{c,i}).Where(x=>x.c.IconId==asset.Id).Select(x=>x.i).OrderBy(i=>i).SequenceEqual(targets.OrderBy(i=>i)),"Outside icon actual != preview");Call(w,"TryHistory",new object[]{false,null});
    Call(w,"SelectTool",EditorTool.DarkBrush);Call(w,"MaterialChosen");Check((EditorTool)Get(w,"currentTool")==EditorTool.Brush,"DarkBrush selection");Call(w,"SelectTool",EditorTool.DarkBucket);Call(w,"MaterialChosen");Check((EditorTool)Get(w,"currentTool")==EditorTool.Brush,"DarkBucket selection");
   }
   Console.WriteLine("stamp PASS: side/corner + filled/outline + both orientations, preview-production Fog/Dark gesture and Undo, Dark selection to Brush");
  }
  [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);
  static void Controls()
  {
   using(var f=new DarkForm())using(var s=new SwitchBox{Text="Zachowaj rozmieszczenie wariantów",AutoSize=true}){f.Controls.Add(s);f.Show();Check(s.AccessibleRole==AccessibleRole.CheckButton,"Accessibility role");Call(s,"OnClick",EventArgs.Empty);Check(s.Checked,"Label click");using(var b=new Bitmap(s.Width,s.Height)){s.DrawToBitmap(b,s.ClientRectangle);s.Enabled=false;s.DrawToBitmap(b,s.ClientRectangle);Check(s.Checked,"On+disabled lost state");}s.Enabled=true;Key(s,Keys.Space);}
   using(var d=new RenameProjectDialog("Mapa.z.kropką.hexmap",x=>true)){d.Show();var layout=(TableLayoutPanel)d.Controls.OfType<TableLayoutPanel>().Single();var labels=layout.Controls.OfType<Label>().ToArray();Check(labels.Where(l=>layout.GetColumn(l)==0).All(l=>l.Text.EndsWith(":")&&l.TextAlign==ContentAlignment.MiddleRight),"Rename labels");Check(((TextBox)Get(d,"name")).Text=="Mapa.z.kropką"&&labels.Any(l=>l.Text=="Mapa.z.kropką"),"Rename extension presentation");Check(ProjectCreation.PathForName(AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar),"Mapa.z.kropką.hexmap").EndsWith("Mapa.z.kropką.hexmap"),"Single extension");}
   using(var w=new MainWindow(Data(),null)){w.Show();var menu=(MenuStrip)Get(w,"mainMenu");Check(menu.Items.Count==6,"Six menus");var zoom=(Button)Get(w,"zoomButton");Check(zoom.Width>=TextRenderer.MeasureText("12800% ▾",w.Font,Size.Empty,TextFormatFlags.NoPadding).Width&&zoom.Width<110,"Zoom width");Call(w,"ShowZoomMenu");var popup=(ContextMenuStrip)Get(w,"zoomPopup");Check(popup.Visible,"Zoom open");Call(w,"ShowZoomMenu");Check(!popup.Visible&&!popup.IsDisposed,"Zoom close/Disposed");Call(w,"ShowZoomMenu");popup.Close(ToolStripDropDownCloseReason.Keyboard);Call(w,"ShowZoomMenu");Check(popup.Visible,"Zoom reopen");popup.Close();
    Call(w,"AdoptNewProject",Data(),null);var save=(Button)Get(w,"saveButton");Check(save.BackColor==ChoiceStyle.ActiveBack&&save.FlatAppearance.BorderColor==ChoiceStyle.ActiveBorder,"Save blue");Call(w,"SetLowQuality",true);Check(((Button)Get(w,"qualityButton")).BackColor==ChoiceStyle.ActiveBack,"Low blue");
    var beforeBounds=w.Bounds;SendMessage(w.Handle,0x112,(IntPtr)0xf030,IntPtr.Zero);SendMessage(w.Handle,0x112,(IntPtr)0xf120,IntPtr.Zero);Check(Math.Abs(w.Width-beforeBounds.Width)<3&&Math.Abs(w.Height-beforeBounds.Height)<3,"Native fallback restore bounds");
    MainWindow.WriteProjectData(Data(),Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Próba 0.8.1.hexmap"),false);
   }
   Console.WriteLine("controls PASS: switch checked/disabled paint, rename labels/single extension, zoom open/close/reopen, exact ChoiceStyle, six menus");
  }
  [STAThread]static int Main(string[] args){try{if(args.Length!=1)throw new Exception("One explicit Case required");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);switch(args[0]){case "fields":Fields();break;case "stamp":Stamp();break;case "controls":Controls();break;default:throw new Exception("Unknown Case");}return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 }
